'use strict';
const $=s=>document.querySelector(s), app=$('#app'), data=window.OAB_DATA;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n).toFixed(2).replace('.',',');
const KEY='pratica-oab-v1';let saved={drafts:{},history:[]};
try{const x=JSON.parse(localStorage.getItem(KEY));if(x&&x.drafts&&Array.isArray(x.history))saved=x;}catch{}
let view='library',area='',edition='',page=1,current=null,index=0,mode='answer',timer=null;
const exams=data?data.exams.sort((a,b)=>b.edition-a.edition||a.area.localeCompare(b.area)):[];
function persist(){try{localStorage.setItem(KEY,JSON.stringify(saved));}catch{toast('Não foi possível salvar neste navegador. Exporte suas respostas.');}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function title(k,t,p=''){return `<section class="heading"><p class="eyebrow">${k}</p><h1>${t}</h1>${p?`<p>${p}</p>`:''}</section>`;}
function navigate(v){clearInterval(timer);view=v;document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===v));if(v==='library')library();if(v==='history')history();if(v==='sources')sources();window.scrollTo(0,0);}
function library(){app.innerHTML=title('OAB · SEGUNDA FASE TRABALHISTA','Sua prática em Direito do Trabalho.','Escolha uma edição e treine a peça trabalhista e as questões discursivas.')+`<section class="overview" aria-label="Banco de provas"><div class="stat"><b>${data.meta.questionCount}</b><span>questões discursivas<br>de exames anteriores</span></div><div class="stat"><b>${exams.length}</b><span>provas completas<br>com peça profissional</span></div><div class="stat"><b>10</b><span>pontos por prova<br>meta de 6 para aprovação</span></div></section><div class="workspace"><aside class="filters"><h2>Encontre sua prova</h2><label class="field">Área do Direito<select id="area" aria-label="Área do Direito">${[...new Set(exams.map(e=>e.area))].sort().map(x=>`<option ${x===area?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label class="field">Edição do exame<select id="edition" aria-label="Edição do exame"><option value="">Todas as edições</option>${[...new Set(exams.map(e=>e.edition))].map(x=>`<option value="${x}" ${String(x)===edition?'selected':''}>${x}º Exame</option>`).join('')}</select></label><div class="rule"><strong>O formato da 2ª fase</strong><p class="hint">1 peça profissional · 5 pontos<br>4 questões · 1,25 ponto cada<br>5 horas · Nota de referência: 6</p></div><p class="hint">Ao terminar, confira o espelho e atribua os pontos. A soma é automática.</p></aside><section><div class="section-bar"><h2>Provas para praticar</h2><span id="count" class="count"></span></div><div id="cards" class="cards"></div><div id="pagination" class="pagination"></div></section></div>`;$('#area').onchange=e=>{area=e.target.value;page=1;cards();};$('#edition').onchange=e=>{edition=e.target.value;page=1;cards();};cards();}
function cards(){const filtered=exams.filter(e=>(!area||e.area===area)&&(!edition||e.edition===+edition));const pages=Math.max(1,Math.ceil(filtered.length/8));page=Math.min(page,pages);$('#count').textContent=`${filtered.length} ${filtered.length===1?'prova':'provas'}`;$('#cards').innerHTML=filtered.slice((page-1)*8,page*8).map(e=>`<article class="card"><div class="card-top"><span class="exam-number">${e.edition}º EXAME DE ORDEM</span><span class="tag">2ª fase</span></div><h3>Direito ${e.area==='Trabalho'?'do ':''}${esc(e.area)}</h3><p>Peça profissional + 4 questões discursivas</p><div class="card-foot"><small>5 horas · 10 pontos</small><button class="primary" data-start="${esc(e.id)}">${saved.drafts[e.id]?'Continuar':'Iniciar prova'}</button></div></article>`).join('')||'<p class="empty">Nenhuma prova encontrada com esses filtros.</p>';$('#pagination').innerHTML=`<span>Página ${page} de ${pages}</span><button class="secondary" id="prev" ${page===1?'disabled':''}>Anterior</button><button class="secondary" id="next" ${page===pages?'disabled':''}>Próxima</button>`;$('#prev').onclick=()=>{page--;cards();};$('#next').onclick=()=>{page++;cards();};document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>start(b.dataset.start));}
function start(id){current=exams.find(e=>e.id===id);if(!current)throw Error('Prova inexistente');if(!saved.drafts[id])saved.drafts[id]={answers:Array(5).fill(''),scores:Array(5).fill(null),deadline:Date.now()+5*60*60*1000,mode:'answer',index:0};const d=saved.drafts[id];index=d.index||0;mode=d.mode||'answer';view='exam';persist();renderExam();window.scrollTo(0,0);}
function draft(){return saved.drafts[current.id];}
function renderRubric(text){const lines=text.split('\n');let out='',table=false;for(const line of lines){if(line.trim().startsWith('|')){if(/^\s*\|\s*:?-/.test(line))continue;if(!table){out+='<table><tbody>';table=true;}out+='<tr>'+line.trim().slice(1,-1).split('|').map(s=>`<td>${esc(s.trim()==='nan'?'':s.trim())}</td>`).join('')+'</tr>';}else{if(table){out+='</tbody></table>';table=false;}out+=esc(line)+'\n';}}return out+(table?'</tbody></table>':'');}
function renderExam(){clearInterval(timer);const d=draft(),q=current.items[index],answered=d.answers.filter(s=>s.trim()).length;app.innerHTML=`<button class="back" id="back">Voltar aos simulados</button>`+title(`${current.edition}º EXAME · DIREITO DO ${esc(current.area.toUpperCase())}`,mode==='review'?'Confira sua resposta.':'Uma etapa de cada vez.',mode==='review'?'Compare com o espelho e registre a pontuação de cada resposta.':'Fundamente suas respostas. Seu texto é salvo automaticamente neste navegador.')+`<div class="notice">${mode==='review'?'Autoavaliação orientada pelo espelho. A nota não é uma correção oficial ou automática do conteúdo.':'A prova tem 1 peça e 4 questões. O cronômetro continua correndo se você sair desta tela.'}</div><div class="exam-layout"><aside class="exam-sidebar"><div class="timer"><span>${mode==='review'?'RESPOSTAS CONCLUÍDAS':'TEMPO RESTANTE'}</span><strong id="time">${mode==='review'?'Correção':'05:00:00'}</strong></div><div class="steps">${current.items.map((x,i)=>`<button class="step ${i===index?'active':''}" data-step="${i}" aria-current="${i===index?'step':'false'}">${i===0?'Peça':`Questão ${i}`}<small>${mode==='review'?(d.scores[i]===null?'Pendente':fmt(d.scores[i])):(d.answers[i].trim()?'✓':'—')}</small></button>`).join('')}</div><div class="progress"><span style="width:${answered*20}%"></span></div><p class="hint">${answered} de 5 respostas preenchidas</p><button class="secondary" id="export">Exportar respostas</button><p class="hint"><a href="${esc(current.sourceUrl)}" target="_blank" rel="noopener">Consultar fonte original</a></p></aside><section class="paper"><div class="section-bar"><h2>${esc(q.title)}</h2><span class="tag">Até ${fmt(q.max)} pontos</span></div><div class="statement">${esc(q.statement)}</div><label class="answer-label" for="answer">Sua resposta <span id="chars">${d.answers[index].length} caracteres</span></label><textarea class="answer" id="answer" ${mode==='review'?'readonly':''} placeholder="Escreva sua resposta com a fundamentação jurídica…">${esc(d.answers[index])}</textarea>${mode==='review'?`<details open><summary>Espelho de correção</summary><div class="rubric">${renderRubric(q.rubric)}</div></details><div class="score-field"><label for="score">Pontuação desta resposta</label><input id="score" type="number" min="0" max="${q.max}" step="0.01" value="${d.scores[index]??''}" inputmode="decimal"><span>/ ${fmt(q.max)}</span><p class="hint">Use a distribuição de pontos do espelho. Resposta em branco vale zero.</p></div>`:''}<div class="actions"><button class="secondary" id="previous-item" ${index===0?'disabled':''}>Anterior</button>${index<4?'<button class="primary" id="next-item">Próxima questão</button>':`<button class="primary" id="finish">${mode==='review'?'Ver minha pontuação':'Concluir respostas'}</button>`}</div></section></div>`;$('#back').onclick=()=>navigate('library');$('#answer').oninput=e=>{d.answers[index]=e.target.value;$('#chars').textContent=`${e.target.value.length} caracteres`;persist();};document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>goItem(+b.dataset.step));$('#previous-item').onclick=()=>goItem(index-1);if($('#next-item'))$('#next-item').onclick=()=>goItem(index+1);if($('#finish'))$('#finish').onclick=mode==='review'?finish:submit;$('#export').onclick=exportAnswers;if($('#score'))$('#score').onchange=()=>saveScore();if(mode==='answer'){timer=setInterval(tick,1000);tick();}}
function saveScore(){if(mode!=='review')return true;const el=$('#score');if(!el)return true;if(el.value===''){draft().scores[index]=null;persist();return true;}const n=Number(el.value);if(!Number.isFinite(n)||n<0||n>current.items[index].max||Math.abs(n*100-Math.round(n*100))>1e-6){toast(`Informe uma nota de 0 a ${fmt(current.items[index].max)}, com até duas casas decimais.`);el.focus();return false;}if(!draft().answers[index].trim()&&n!==0){toast('Resposta em branco recebe zero.');el.value='0';draft().scores[index]=0;}else draft().scores[index]=n;persist();return true;}
function goItem(n){if(n<0||n>4||!saveScore())return;index=n;draft().index=n;persist();renderExam();window.scrollTo(0,0);}
function tick(){if(mode!=='answer'||view!=='exam')return;const secs=Math.max(0,Math.ceil((draft().deadline-Date.now())/1000));const el=$('#time');if(el)el.textContent=[Math.floor(secs/3600),Math.floor(secs%3600/60),secs%60].map(n=>String(n).padStart(2,'0')).join(':');if(secs===0){clearInterval(timer);toReview();toast('O tempo terminou. Confira suas respostas pelo espelho.');}}
async function confirmAction(t,p){$('#confirm-title').textContent=t;$('#confirm-text').textContent=p;const dlg=$('#confirm');dlg.returnValue='cancel';dlg.showModal();return new Promise(resolve=>dlg.addEventListener('close',()=>resolve(dlg.returnValue==='ok'),{once:true}));}
async function submit(){const blank=draft().answers.filter(a=>!a.trim()).length;if(await confirmAction('Concluir respostas?',`${blank?`${blank} resposta(s) em branco receberão zero. `:''}O texto será encerrado e você passará à correção pelo espelho.`))toReview();}
function toReview(){const d=draft();mode=d.mode='review';d.answers.forEach((a,i)=>{if(!a.trim())d.scores[i]=0;});index=d.index=0;persist();renderExam();}
function totalScore(scores){return scores.reduce((sum,n)=>sum+Math.round(n*100),0)/100;}
function finish(){if(!saveScore())return;const d=draft(),missing=d.scores.findIndex(s=>s===null);if(missing!==-1){goItem(missing);toast('Registre a pontuação de todas as cinco respostas.');return;}const result={id:Date.now().toString(),examId:current.id,edition:current.edition,area:current.area,scores:[...d.scores],answers:[...d.answers],total:totalScore(d.scores),date:new Date().toISOString()};saved.history.unshift(result);delete saved.drafts[current.id];persist();showResult(result);}
function showResult(r){clearInterval(timer);view='result';app.innerHTML=title(`${r.edition}º EXAME · DIREITO DO ${esc(r.area.toUpperCase())}`,'Seu resultado no simulado.')+`<section class="result-hero"><span>NOTA POR AUTOAVALIAÇÃO</span><strong class="big">${fmt(r.total)} <small style="font-size:22px">/ 10</small></strong><h2>${r.total>=6?'Meta de 6 pontos alcançada':'Continue praticando: a meta é 6 pontos'}</h2><p>Nota calculada a partir dos pontos que você atribuiu pelo espelho.</p></section><table class="result-table"><thead><tr><th>Etapa</th><th>Sua pontuação</th><th>Máximo</th></tr></thead><tbody>${r.scores.map((s,i)=>`<tr><td>${i===0?'Peça profissional':`Questão ${i}`}</td><td>${fmt(s)}</td><td>${i===0?'5,00':'1,25'}</td></tr>`).join('')}</tbody></table><div class="actions"><button class="secondary" id="download-result">Exportar resultado</button><button class="primary" id="new-exam">Escolher outra prova</button></div>`;$('#new-exam').onclick=()=>navigate('library');$('#download-result').onclick=()=>download(`resultado-oab-${r.edition}.json`,JSON.stringify(r,null,2),'application/json');window.scrollTo(0,0);}
function download(name,text,type){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function exportAnswers(){const d=draft();download(`oab-${current.edition}-${current.area}.txt`,`${current.edition}º Exame • ${current.area}\n\n`+current.items.map((q,i)=>`${q.title}\n\n${d.answers[i]||'(Em branco)'}\n\n`).join('\n'),'text/plain;charset=utf-8');}
function history(){app.innerHTML=title('ACOMPANHE SUA EVOLUÇÃO','Meu desempenho.','Resultados de autoavaliações concluídas neste navegador.')+(saved.history.length?`<div class="cards" style="margin-top:28px">${saved.history.map(r=>`<article class="card"><div class="card-top"><span class="exam-number">${r.edition}º EXAME · ${esc(r.area)}</span><span class="tag">${new Date(r.date).toLocaleDateString('pt-BR')}</span></div><h2>${fmt(r.total)} / 10</h2><p>${r.total>=6?'Meta alcançada':'Em preparação'} · Autoavaliação</p><button class="secondary" data-result="${esc(r.id)}">Ver resultado</button></article>`).join('')}</div>`:'<div class="empty" style="margin-top:28px">Você ainda não concluiu um simulado. Escolha uma prova para começar.</div>');document.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>showResult(saved.history.find(r=>r.id===b.dataset.result)));}
function sources(){app.innerHTML=title('TRANSPARÊNCIA NO SEU ESTUDO','Fontes e critérios de correção.')+`<article class="source-card"><h3>Um banco de provas reais</h3><p>${data.meta.questionCount} questões discursivas e ${data.meta.pieceCount} peças profissionais, organizadas em ${exams.length} provas. Cada simulado reúne a peça e as quatro questões de Direito do Trabalho da mesma edição.</p><p><a href="https://github.com/maritaca-ai/oab-bench" target="_blank" rel="noopener">OAB-Bench · Maritaca AI, no GitHub</a> — conjunto aberto de enunciados e espelhos. Dados incorporados ao projeto para funcionar sem chave de API.</p><p><a href="https://oab.fgv.br/" target="_blank" rel="noopener">FGV · Arquivo oficial do Exame de Ordem</a> — provas complementares e padrões de resposta. O link específico da fonte está dentro de cada simulado.</p></article><article class="source-card"><h3>Como sua nota é calculada</h3><p>A peça vale até 5 pontos e cada uma das quatro questões vale até 1,25 ponto. Após escrever, compare a resposta com o espelho e informe os pontos obtidos. A soma é calculada automaticamente, até 10 pontos, com referência de 6 para a meta do simulado.</p><p>A plataforma não avalia automaticamente o conteúdo jurídico. O resultado depende da autoavaliação; para uma correção técnica, peça a um professor que confira os textos e o espelho.</p><p><a href="https://www.oab.org.br/leisnormas/legislacao/provimentos/144-2011" target="_blank" rel="noopener">Consulte as regras do Exame de Ordem</a>. Os espelhos refletem a época de cada prova; legislação e jurisprudência podem ter mudado.</p></article><article class="source-card"><h3>Seu progresso fica neste navegador</h3><p>Rascunhos, notas e histórico são guardados localmente. O cronômetro usa o horário de término salvo. Limpar os dados do navegador remove esse histórico. Exporte suas respostas para manter uma cópia.</p></article>`;}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$('.brand').onclick=e=>{e.preventDefault();navigate('library');};
if(!data){app.innerHTML='<p class="empty">Não foi possível carregar o banco. Confira se data.js está na mesma pasta do index.html e recarregue.</p>';}else navigate('library');
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'list_oab_exams',title:'Listar provas OAB',description:'Consulta as provas disponíveis sem iniciar um simulado.',inputSchema:{type:'object',properties:{area:{type:'string'}},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||typeof input!=='object'||(input.area!==undefined&&typeof input.area!=='string'))throw Error('Área inválida');return exams.filter(e=>!input.area||e.area===input.area).map(e=>({id:e.id,edition:e.edition,area:e.area}));}})).catch(()=>{});}catch{}}
